const created = session.created ? new Date(session.created * 1000) : new Date();
return [{
  json: {
    orderNumber: session.id || 'unknown',
    date: created.toISOString().slice(0, 10),
    amountEur: ((session.amount_total || 0) / 100).toFixed(2),
